import{_ as s,c as n,o as a,a6 as p}from"./chunks/framework.CZHnDj0c.js";const d=JSON.parse('{"title":"一、工业相机从传感器到上位机的信号链流程图","description":"","frontmatter":{},"headers":[],"relativePath":"src/camera/cameraLink.md","filePath":"src/camera/cameraLink.md"}'),l={name:"src/camera/cameraLink.md"},i=p(`<h1 id="一、工业相机从传感器到上位机的信号链流程图" tabindex="-1">一、工业相机从传感器到上位机的信号链流程图 <a class="header-anchor" href="#一、工业相机从传感器到上位机的信号链流程图" aria-label="Permalink to &quot;一、工业相机从传感器到上位机的信号链流程图&quot;">​</a></h1><ol><li><p>Camera Link是由AIA（Automated Imaging Association）制定的工业相机接口标准，面向高速、低时延的图像传输，采用LVDS并行传输并定义了统一的物理连接器与线缆。标准包含Base/Medium/Full三档配置：Base使用4个数据通道，Medium使用8个，Full使用12个；在85 MHz像素时钟下，Base约2.0 Gbps、Medium约4.8 Gbps、Full约5.4 Gbps（约680 MB/s）。规范还包含一条双向串行通信通道用于相机参数配置与控制。Camera Link通常需配合帧采集卡（Frame Grabber）使用，典型线缆长度&lt; 10 m</p></li><li><p>Camera Link使用LVDS并行差分信号与专用线缆/连接器（如MDR‑26/SDR‑26），可实现高速、低时延的图像传输，并支持双向串行通信。</p></li></ol><hr><h2 id="📊-工业相机信号链流程图" tabindex="-1"><strong>📊 工业相机信号链流程图</strong> <a class="header-anchor" href="#📊-工业相机信号链流程图" aria-label="Permalink to &quot;**📊 工业相机信号链流程图**&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|      被测物体 (光照)        |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|  工业相机 — Image Sensor   |  ←【传感器】</span></span>
<span class="line"><span>|  (CCD / CMOS 感光阵列)      |</span></span>
<span class="line"><span>|  - 分辨率 (如 8K 线阵)       |</span></span>
<span class="line"><span>|  - 位深 (8/10/12/14bit)     |</span></span>
<span class="line"><span>|  - 全局/卷帘快门             |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|   传感器输出 RAW 数据       |  (可能是 Bayer / Mono)</span></span>
<span class="line"><span>|   → 送入机内 ISP 或直出     |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>          【ISP】(可选)</span></span>
<span class="line"><span>    - 去马赛克 / 3A / 色彩校正</span></span>
<span class="line"><span>    - Gamma / 锐化 / 去噪</span></span>
<span class="line"><span>    - 输出 YUV / RGB / RAW</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|      相机接口层            |</span></span>
<span class="line"><span>|  ┌─────────────────────┐  |</span></span>
<span class="line"><span>|  │ GigE Vision         │ → RJ45 / 网口（无需采集卡）|</span></span>
<span class="line"><span>|  │ USB3 Vision         │ → USB3（无需采集卡）  |</span></span>
<span class="line"><span>|  │ Camera Link         │ → LVDS 差分信号【差分信号】|</span></span>
<span class="line"><span>|  │ CoaXPress (CXP)     │ → 同轴差分信号【差分信号】|</span></span>
<span class="line"><span>|  └─────────────────────┘  |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>   【是否需要采集卡？】</span></span>
<span class="line"><span>   ✅ Camera Link / CXP → 必须 PCIe 采集卡</span></span>
<span class="line"><span>   ❌ GigE / USB3 → 网卡/USB控制器即采集功能</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|   图像采集卡 (Frame Grabber)|</span></span>
<span class="line"><span>|  - PCIe 高速总线传输        |</span></span>
<span class="line"><span>|  - DMA 零拷贝搬运           |</span></span>
<span class="line"><span>|  - 硬件触发 &amp; 同步 I/O      |</span></span>
<span class="line"><span>|  - 缓存 &amp; FPGA 预处理       |</span></span>
<span class="line"><span>|  - PoCL / PoCXP 供电        |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|   上位机 (PC / 工控机)      |</span></span>
<span class="line"><span>|  - CPU / GPU / FPGA 处理    |</span></span>
<span class="line"><span>|  - 算法 (检测/测量/识别)    |</span></span>
<span class="line"><span>|  - 显示 / 存储 / 通信       |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 线阵相机特有参数 ---</span></span>
<span class="line"><span>行频 (Line Rate)：每秒采集的行数 [Hz/kHz]  ←【行频】</span></span>
<span class="line"><span>最高行频：相机 &amp; 接口能保证不丢数据的最大行频 ←【最高行频】</span></span></code></pre></div><hr><h3 id="🔍-各模块作用与关联说明" tabindex="-1"><strong>🔍 各模块作用与关联说明</strong> <a class="header-anchor" href="#🔍-各模块作用与关联说明" aria-label="Permalink to &quot;**🔍 各模块作用与关联说明**&quot;">​</a></h3><ol><li><p><strong>传感器</strong></p><ul><li>将光信号转为电信号（RAW数据）。</li><li>决定分辨率、位深、快门类型、感光能力。</li></ul></li><li><p><strong>ISP（可选）</strong></p><ul><li>若在相机内完成：输出可直接使用的 RGB/YUV。</li><li>若直出 RAW：需在上位机/嵌入式平台完成 ISP。</li></ul></li><li><p><strong>差分信号</strong>（Camera Link / CXP）</p><ul><li>用 LVDS 或同轴差分传输高速数据，抗干扰强、适合短距离高带宽。</li><li>必须通过采集卡转成 PCIe 数据进主机。</li></ul></li><li><p><strong>行频 &amp; 最高行频</strong></p><ul><li>线阵相机每秒输出的行数。</li><li>最高行频受传感器读取速度、接口带宽、采集卡缓存限制。</li><li>选型时要保证<strong>需求行频 ≤ 最高行频</strong>。</li></ul></li><li><p><strong>采集卡</strong></p><ul><li>在 Camera Link / CXP 场景下必不可少。</li><li>提供高速 DMA、硬件触发、同步 I/O、PoCL/PoCXP 供电。</li><li>对 GigE/USB3 相机则不需要额外采集卡（网卡/USB控制器代替）。</li></ul></li><li><p><strong>上位机</strong></p><ul><li>运行视觉算法、显示与存储图像。</li><li>如果是 RAW 数据，这里还要跑 ISP 管线。</li></ul></li></ol><hr><h3 id="🎯-结合你之前的埃科采集卡与相机" tabindex="-1"><strong>🎯 结合你之前的埃科采集卡与相机</strong> <a class="header-anchor" href="#🎯-结合你之前的埃科采集卡与相机" aria-label="Permalink to &quot;**🎯 结合你之前的埃科采集卡与相机**&quot;">​</a></h3><ul><li><p>如果你的相机是 <strong>CXP 接口</strong>（如埃科 Vulcan-CXP 系列），那么流程中：</p><ul><li>相机 → 同轴差分信号 → 埃科采集卡 → PCIe → 上位机。</li><li>行频/最高行频要匹配采集卡的单通道带宽（CXP-6 ≈ 625 MB/s，CXP-12 ≈ 1250 MB/s）。</li><li>采集卡还负责触发同步、PoCXP 供电、多相机拓扑管理。</li></ul></li><li><p>如果是 <strong>GigE 相机</strong>：流程中相机 → RJ45 → 网卡 → 上位机，无需埃科采集卡，行频概念变为帧频。</p></li></ul><hr><p>这样一张图就把<strong>传感器 → ISP → 接口（差分信号） → 采集卡 → 上位机</strong>全串起来了，并且标出了<strong>行频 / 最高行频</strong>的位置，方便你在选型与调试时对照检查。</p>`,13),e=[i];function c(r,t,o,m,g,u){return a(),n("div",null,e)}const h=s(l,[["render",c]]);export{d as __pageData,h as default};
